WITH kept AS (SELECT s.* FROM stores s WHERE NOT EXISTS (SELECT 1 FROM store_sales c WHERE c.store_id = s.id AND c.sale_date >= s.opened_date)) SELECT id, store_name, city, region, opened_date, sqft, CASE WHEN region RLIKE '^(South|Central)$' THEN 'EXTENDED' WHEN region RLIKE '^(North|East)$' THEN 'PRIORITY' ELSE 'GROUP_A' END AS region_zone FROM kept ORDER BY region_zone NULLS FIRST;
